// ─── App ──────────────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

const makeIdle = (modelId: string, provider: Provider): RunState => ({
  modelId,
  provider,
  status: 'idle',
  output: '',
});

export default function App({ topBarRight }: AppProps) {
  const [keys, setKeys] = useState<Keys>(() => loadKeys());
  const [showSettings, setShowSettings] = useState(false);
  const [settingsKeys, setSettingsKeys] = useState<Keys>(keys);

  const [systemPrompt, setSystemPrompt] = useState('');
  const [userPrompt, setUserPrompt] = useState('');
  const [compare, setCompare] = useState(false);
  const [model1, setModel1] = useState(MODELS[0].id);
  const [model2, setModel2] = useState(MODELS[3].id);
  const [runs, setRuns] = useState<RunState[]>([]);
  const [running, setRunning] = useState(false);
  const abortRef = useRef<AbortController | null>(null);

  const [saveOpen, setSaveOpen] = useState(false);
  const [currentDoc, setCurrentDoc] = useState<{ id: string; name: string } | null>(null);

  // ─── Key management ──────────────────────────────────────────────────────

  const handleInitialKeys = (k: Keys) => {
    setKeys(k);
    saveKeys(k);
  };

  const handleSaveSettings = () => {
    setKeys(settingsKeys);
    saveKeys(settingsKeys);
    setShowSettings(false);
  };

  // ─── Model helpers ───────────────────────────────────────────────────────

  const getProvider = (modelId: string): Provider =>
    MODELS.find((m) => m.id === modelId)?.provider ?? 'groq';

  const getKeyForModel = (modelId: string): string => {
    const provider = getProvider(modelId);
    return keys[provider];
  };

  const availableModels = useMemo(
    () => MODELS.filter((m) => keys[m.provider]),
    [keys],
  );

  // ─── Run ─────────────────────────────────────────────────────────────────

  const canRun = Boolean(userPrompt.trim()) && availableModels.length > 0;

  const handleRun = useCallback(async () => {
    if (!canRun || running) return;
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    const models = compare ? [model1, model2] : [model1];
    const initial = models.map((m) => makeIdle(m, getProvider(m)));
    setRuns(initial);
    setRunning(true);

    await Promise.allSettled(
      models.map(async (modelId, idx) => {
        const provider = getProvider(modelId);
        const key = keys[provider];
        if (!key) {
          setRuns((prev) => prev.map((r, i) => i === idx ? { ...r, status: 'error', error: `No ${provider} API key configured` } : r));
          return;
        }
        setRuns((prev) => prev.map((r, i) => i === idx ? { ...r, status: 'streaming' } : r));
        const start = Date.now();
        try {
          await runModel(
            provider,
            key,
            modelId,
            systemPrompt,
            userPrompt,
            (chunk) => {
              setRuns((prev) =>
                prev.map((r, i) => i === idx ? { ...r, output: r.output + chunk } : r),
              );
            },
            controller.signal,
          );
          const duration = Date.now() - start;
          setRuns((prev) =>
            prev.map((r, i) => i === idx ? { ...r, status: 'done', durationMs: duration } : r),
          );
        } catch (err: unknown) {
          if (controller.signal.aborted) return;
          const msg = err instanceof Error ? err.message : String(err);
          setRuns((prev) =>
            prev.map((r, i) => i === idx ? { ...r, status: 'error', error: msg } : r),
          );
        }
      }),
    );

    setRunning(false);
  }, [canRun, running, compare, model1, model2, keys, systemPrompt, userPrompt]);

  // ─── Save / Load ─────────────────────────────────────────────────────────

  const handleSaveDoc = async (name: string) => {
    setSaveOpen(false);
    const content = JSON.stringify({ systemPrompt, userPrompt, model1, model2, compare });
    if (currentDoc) {
      await updateDoc(currentDoc.id, name, content);
      setCurrentDoc({ id: currentDoc.id, name });
    } else {
      const id = await saveDoc('promptlab', name, content);
      setCurrentDoc({ id, name });
    }
  };

  const handleLoadDoc = (content: string, docId?: string, docName?: string) => {
    try {
      const data = JSON.parse(content);
      if (data.systemPrompt != null) setSystemPrompt(data.systemPrompt);
      if (data.userPrompt != null) setUserPrompt(data.userPrompt);
      if (data.model1) setModel1(data.model1);
      if (data.model2) setModel2(data.model2);
      if (data.compare != null) setCompare(data.compare);
      setCurrentDoc(docId && docName ? { id: docId, name: docName } : null);
    } catch { /* ignore parse errors */ }
  };

  // ─── First-run guard ─────────────────────────────────────────────────────

  if (!hasAnyKey(keys)) {
    return (
      <Layout title="Prompt Lab" sidebar={null} topBarRight={topBarRight}>
        <ApiKeySetup onSave={handleInitialKeys} />
      </Layout>
    );
  }

  // ─── Top bar ─────────────────────────────────────────────────────────────

  const topRight = (
    <TopBarBtns>
      <IconBtn active={compare} onClick={() => setCompare((c) => !c)}>
        {compare ? <Columns2 size={13} /> : <Monitor size={13} />}
        {compare ? 'Compare' : 'Single'}
      </IconBtn>
      <DocumentsMenu appId="promptlab" onLoad={handleLoadDoc} />
      <IconBtn onClick={() => setSaveOpen(true)}>
        <Save size={13} /> Save
      </IconBtn>
      <IconBtn onClick={() => { setSettingsKeys(keys); setShowSettings(true); }}>
        <Settings size={13} />
      </IconBtn>
      {topBarRight}
    </TopBarBtns>
  );

  // ─── Display runs (idle defaults) ────────────────────────────────────────

  const displayRuns = runs.length > 0
    ? runs
    : compare
      ? [makeIdle(model1, getProvider(model1)), makeIdle(model2, getProvider(model2))]
      : [makeIdle(model1, getProvider(model1))];

  return (
    <Layout title="Prompt Lab" sidebar={null} topBarRight={topRight}>
      <Content>
        <LeftCol>
          <ModelRow>
            <ModelLabel>Model{compare ? ' 1' : ''}</ModelLabel>
            <ModelSelect value={model1} onChange={(e) => setModel1(e.target.value)}>
              {availableModels.map((m) => (
                <option key={m.id} value={m.id}>
                  {m.label} ({m.provider})
                </option>
              ))}
            </ModelSelect>
          </ModelRow>
          {compare && (
            <ModelRow>
              <ModelLabel>Model 2</ModelLabel>
              <ModelSelect value={model2} onChange={(e) => setModel2(e.target.value)}>
                {availableModels.map((m) => (
                  <option key={m.id} value={m.id}>
                    {m.label} ({m.provider})
                  </option>
                ))}
              </ModelSelect>
            </ModelRow>
          )}
          <PromptEditor
            systemPrompt={systemPrompt}
            userPrompt={userPrompt}
            onSystemChange={setSystemPrompt}
            onUserChange={setUserPrompt}
            onRun={handleRun}
            running={running}
            canRun={canRun}
          />
        </LeftCol>
        <RightCol>
          {displayRuns.map((run, i) => (
            <PanelWrap key={`${run.modelId}-${i}`}>
              <ResponsePanel run={run} />
            </PanelWrap>
          ))}
        </RightCol>
      </Content>

      {showSettings && (
        <SettingsOverlay>
          <SettingsHeader>
            <SettingsTitle>API Keys</SettingsTitle>
            <CloseBtn onClick={() => setShowSettings(false)}>
              <X size={18} />
            </CloseBtn>
          </SettingsHeader>
          <SettingsBody>
            {PROVIDERS.map((p) => (
              <FieldGroup key={p.id}>
                <LabelRow>
                  <FieldLabel>{p.label}</FieldLabel>
                  <GetKeyLink href={p.url} target="_blank" rel="noopener noreferrer">
                    Get key <ExternalLink size={10} />
                  </GetKeyLink>
                </LabelRow>
                <KeyInput
                  type="password"
                  placeholder={`Paste your ${p.label} API key`}
                  value={settingsKeys[p.id]}
                  onChange={(e) => setSettingsKeys((prev) => ({ ...prev, [p.id]: e.target.value }))}
                />
              </FieldGroup>
            ))}
            <SaveSettingsBtn onClick={handleSaveSettings}>Save Keys</SaveSettingsBtn>
          </SettingsBody>
        </SettingsOverlay>
      )}

      {saveOpen && (
        <SaveDialog
          existingDoc={currentDoc ?? undefined}
          onSave={handleSaveDoc}
          onUpdate={currentDoc ? async () => {
            setSaveOpen(false);
            const content = JSON.stringify({ systemPrompt, userPrompt, model1, model2, compare });
            await updateDoc(currentDoc.id, currentDoc.name, content);
          } : undefined}
          onCancel={() => setSaveOpen(false)}
        />
      )}
    </Layout>
  );
}
